func TestSettersSequenceStopCondition(t *testing.T) {
	t.Run("SetMatchConfig", func(t *testing.T) {
		obj := &SequenceStopCondition{}
		var fernTestValueMatchConfig *SequenceStopConditionMatchConfig
		obj.SetMatchConfig(fernTestValueMatchConfig)
		assert.Equal(t, fernTestValueMatchConfig, obj.MatchConfig)
		assert.NotNil(t, obj.explicitFields)
	})

	t.Run("SetType", func(t *testing.T) {
		obj := &SequenceStopCondition{}
		var fernTestValueType *SequenceStopConditionType
		obj.SetType(fernTestValueType)
		assert.Equal(t, fernTestValueType, obj.Type)
		assert.NotNil(t, obj.explicitFields)
	})

	t.Run("SetValue", func(t *testing.T) {
		obj := &SequenceStopCondition{}
		var fernTestValueValue *string
		obj.SetValue(fernTestValueValue)
		assert.Equal(t, fernTestValueValue, obj.Value)
		assert.NotNil(t, obj.explicitFields)
	})

}

